{
  "findings": [
    {
      "check_id": "CKV_AZURE_26",
      "title": "Ensure that 'Send Alerts To' is enabled for MSSQL servers",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The email_account_admins flag is not set to 'Enabled', which may delay response from administrators and subscription owners in case of a security threat."
    }
  ],
  "patched_code": "resource "azurerm_mssql_server_security_alert_policy" "alertpolicy6" {
  resource_group_name        = azurerm_resource_group.example.name
  server_name                = azurerm_mssql_server.mssql6.name
  state                      = "Enabled"
  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint
  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key
  disabled_alerts = [
    "Sql_Injection",
    "Data_Exfiltration"
  ]
  retention_days  = 20
  email_addresses = ["securityengineer@bridgecrew.io"]
  email_account_admins = "Enabled"
}",
  "fix_summary": "Added 'email_account_admins = "Enabled"' to the MSSQL server security alert policy to ensure alerts are sent to account admins."
}
